-- Brand kit part 3, Templates, locked by Sean 2026-11-11 ("Lock it, go with your defaults"). Safe to run twice.
insert into public.knowledge_records (slug,title,category,subcategory,body,status,owner,always_load,load_priority,tags,version,change_summary,created_by,updated_by)
select 'canon-ve-brand-kit-templates','Vegans Explore brand kit, part 3: Templates (LOCKED)','brand','canonical',$j${
"authority":"Sean, 2026-11-11: \"Lock it, go with your defaults\" after four rounds of notes (\"this is tight, tight, tight. I love it\").",
"reference":"/mocks/brand-kit/templates (11 slides). Built on canon-ve-brand-kit-foundations and canon-ve-brand-kit-imagery.",
"principle":"Every template is a door from the Color Block concept: a section color, a label in a solid block, big words, the picture whole in a white frame with an ink shadow, the stripe. Words never sit on a picture.",
"carousel_post":"4:5, 1080x1350. A square scene drawn square (1080x1080) on top; below, the section-color band with the suitcase mark left of a two-row headline (white mark on dark, ink on light); slide number right on inside slides; stripe along the bottom. Ten slides: cover, eight inside, end card. End card: a city drawn 16:9 on top (New York the first), then the white landscape logo, the headline (second row bright green), one line, a big full-width Join free with an ink outline and a white hard shadow.",
"story_reel_cover":"9:16, 1080x1920. Top 570 px section color: the first 250 px hold only color (Instagram's bar); the section label in an ink block starts right below; the mark left of a two-row headline at the bottom; the stripe where the band meets the picture. Bottom 1350 px: one 4:5 scene, whole. Nothing that matters in the bottom 340 px. Reel shots keep the band still; only the picture moves.",
"thumbnail_share":"YouTube 16:9 1280x720 and share image 1200x630: the section color; an ink label; each headline line its own solid block (white with ink text, ink with white text, or bright green) with a hard shadow, two rows, at most four words; the landscape logo as a third white block under the title; the 4:5 scene full height on the right in a white frame with an ink shadow; the mosaic top right; the stripe. No arrows, circles or pasted faces.",
"video":"Open: under 1 s, the stripe whips across (0.25 s), the white portrait logo punches in by 0.6 s, holds, cut. Lower third: a white plate in a clear corner (never over a face): the person's universal profile picture exactly as tall as the words (name, role, a pink link row like vegansexplore.com/liz), the stripe under the plate, a pink hard shadow. Close (last 20 s): dark green, the white landscape logo, a two-row headline, Join free, the site; end-screen spots framed in white with orange shadows, Subscribe inside a pink circle. Scenes for video are drawn 16:9 with a clear corner.",
"podcast_cover":"3000x3000: Media peach, Every Sunday, VEGANS EXPLORE in 900, PODCAST spaced; the suitcase mark alone top right (the name is already there); the show's skyline redrawn 16:9 for its window in a white frame with an orange shadow. Today's cover gets the white suitcase bottom right. City shows: the same frame, their city drawn for it.",
"email":"600 px: a 6 px stripe across the top, the landscape logo on white, an optional 21:9 strip picture drawn for it, one headline with one marker phrase, a short paragraph, one orange button with a tracked /go/ link, footer with why they get it, {{unsubscribe_url}} and {{postal_address}}. Sean loved it as is. The email-send button turns orange.",
"ads":"Little doors with a 2px ink outline. 300x250 and 300x600: section color, ink label, big line, the picture (strip or 4:5) in a white frame with an ink shadow, a white sign-off bar at the bottom with the landscape logo and one button. 728x90 leaderboard: dark green, framed strip, two-row line, the white landscape logo exactly as tall as the Join free button. 320x50: the suitcase, one line, one button, the stripe.",
"production":"Each template becomes a render script in scripts/brand-templates/ (Playwright, like the creator kit): words plus a picture from its asset pack, with the face check built in. The KJ creator kit and the city carousel are re-set on the band layout one at a time; carousel scenes are drawn square."
}$j$::jsonb,'active','sar',false,20,array['vegans-explore','brand','brand-kit','templates','canon'],1,'Created: Sean locked Templates with all defaults.','logan','logan'
where not exists (select 1 from public.knowledge_records where slug='canon-ve-brand-kit-templates');

update public.knowledge_records set version=5, updated_by='logan', updated_at=now(),
  change_summary='v5 (Sean, 2026-11-11, Templates lock): landscape v2 built from the portrait replaces v1 everywhere; the suitcase mark files and the one-color ink logo join the set; the suitcase means Vegans Explore approved.',
  body = jsonb_set(jsonb_set(body, '{landscape_v2}', $j$"Sean: \"the vegans isn't the same weight as the portrait view. It should be the same weight.\" The landscape logo is now built from the portrait v2's own mark and letters (scripts/brand-logo-build.py): /public/logo-ve-landscape-v2.svg, -inverted, -white, -ink. It replaced v1 in the header, footer, sign-in and every page; the v1 file names now serve the v2 drawing so emails and edge functions show it too; the retired v1 is at /public/brand-kit/logo-before/*-retired.svg and in git."$j$::jsonb), '{set}', $j$"The set: portrait v2 (full color on white, inverted on black, all-white on dark green and pictures, ink on orange, pink, peach and the greens), landscape v2 (same four), and the suitcase mark alone (/public/logo-ve-mark.svg, -white, -ink, -inverted) for small spots and as a seal. Sean: \"when they see that suitcase, that means it's a Vegans Explore approved.\" Small (a band, a story, a 320x50 ad, a cover that already says Vegans Explore): the mark alone. The logo lives in the color, never a white chip on a picture."$j$::jsonb)
where slug='canon-ve-logo' and status='active' and version=4;
